<template>
  <div class="question">
    <div class="text-container">
      <span class="typewriter-text">{{ displayText }}</span>
      <span v-if="showCursor" class="cursor">|</span>
    </div>
    <div class="buttons" v-if="showButtons">
      <button class="choice-btn" @click="onAccept">愿意</button>
      <button class="choice-btn decline" @click="onDecline">不愿意</button>
    </div>
  </div>
</template>

<script setup lang="ts">
import { useGameStore, GamePhase } from '../store';

const store = useGameStore();
const fullText = '但……你愿意，试试吗？';
const displayText = ref('');
const showCursor = ref(true);
const showButtons = ref(false);

onMounted(() => {
  // 黑屏3秒后开始打字
  setTimeout(() => {
    let i = 0;
    const typeInterval = setInterval(() => {
      if (i < fullText.length) {
        displayText.value += fullText[i];
        i++;
      } else {
        clearInterval(typeInterval);
        showCursor.value = false;
        // 打完后显示按钮
        setTimeout(() => {
          showButtons.value = true;
        }, 1000);
      }
    }, 200);
  }, 3000);
});

function onAccept() {
  showButtons.value = false;
  displayText.value = '';
  store.setPhase(GamePhase.SHOOTER_PHASE1);
}

function onDecline() {
  showButtons.value = false;
  displayText.value = '';
  store.setPhase(GamePhase.END);
}
</script>

