<template>
  <div class="player-danmaku">
    <!-- 弹幕层 - 固定行轨道 -->
    <div class="danmaku-layer">
      <div v-for="item in activeDanmakus" :key="item.key" class="danmaku-item" :style="item.style">
        <img
          v-if="item.avatar"
          :src="item.avatar"
          class="danmaku-avatar"
          @error="(e: Event) => ((e.target as HTMLImageElement).style.display = 'none')"
        />
        <div v-else class="danmaku-avatar-placeholder" :style="{ background: item.color }">
          {{ item.initial }}
        </div>
        <span class="danmaku-name">{{ item.name }}</span>
        <span class="danmaku-text">{{ item.text }}</span>
      </div>
    </div>

    <!-- 汇聚文字 -->
    <div class="final-message" :class="{ show: showFinalMessage }">
      <span class="final-text">潮汐，我爱你。</span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { assignLine, getDisplayName } from '../data';
import { GamePhase, useGameStore } from '../store';

const store = useGameStore();
const showFinalMessage = ref(false);

interface DanmakuItem {
  key: string;
  name: string;
  text: string;
  avatar: string | null;
  initial: string;
  color: string;
  style: Record<string, string>;
}

const activeDanmakus = ref<DanmakuItem[]>([]);

// 固定行轨道系统 - 防止弹幕遮挡
const TRACK_COUNT = 16; // 16条轨道
const trackAvailable = new Array(TRACK_COUNT).fill(0); // 每条轨道的可用时间戳

const COLORS = [
  '#e74c3c',
  '#e67e22',
  '#f39c12',
  '#2ecc71',
  '#1abc9c',
  '#3498db',
  '#9b59b6',
  '#e91e63',
  '#00bcd4',
  '#ff5722',
];

function randomColor(seed: string) {
  let hash = 0;
  for (const ch of seed) hash = ((hash << 5) - hash + ch.charCodeAt(0)) | 0;
  return COLORS[Math.abs(hash) % COLORS.length];
}

function findAvailableTrack(): number {
  const now = Date.now();
  // 找最早可用的轨道
  let bestTrack = 0;
  let bestTime = trackAvailable[0];
  for (let i = 1; i < TRACK_COUNT; i++) {
    if (trackAvailable[i] < bestTime) {
      bestTime = trackAvailable[i];
      bestTrack = i;
    }
  }
  return bestTrack;
}

let danmakuIndex = 0;
let danmakuTimeout: ReturnType<typeof setTimeout>;
let keyCounter = 0;
let finished = false;

// 定时清理已滚完的弹幕（通过创建时间+动画时长判断）
const danmakuMeta: Map<string, { createdAt: number; duration: number }> = new Map();

function cleanupOldDanmakus() {
  const now = Date.now();
  const toRemove: string[] = [];
  for (const [key, meta] of danmakuMeta) {
    if (now - meta.createdAt > meta.duration * 1000 + 500) {
      toRemove.push(key);
    }
  }
  if (toRemove.length > 0) {
    const removeSet = new Set(toRemove);
    activeDanmakus.value = activeDanmakus.value.filter(d => !removeSet.has(d.key));
    for (const key of toRemove) danmakuMeta.delete(key);
  }
}

function spawnDanmaku() {
  const players = store.players;
  if (danmakuIndex >= players.length) {
    if (finished) return;
    finished = true;
    // 全部出完，等最后的弹幕滚完再汇聚
    console.info('[潮汐IF线] 所有555条弹幕已发出，等待汇聚');
    setTimeout(() => {
      activeDanmakus.value = [];
      danmakuMeta.clear();
      showFinalMessage.value = true;

      // 显示4秒后进入第二阶段射击
      setTimeout(() => {
        console.info('[潮汐IF线] 进入射击第二阶段');
        store.setPhase(GamePhase.SHOOTER_PHASE2);
      }, 4000);
    }, 5000); // 给最后的弹幕5秒滚完
    return;
  }

  // 先清理已滚完的弹幕
  cleanupOldDanmakus();

  const p = players[danmakuIndex];
  const name = getDisplayName(p);
  const text = assignLine(danmakuIndex);
  const track = findAvailableTrack();

  // 弹幕时长：稍短一些让整体节奏更快
  const duration = 10 + Math.random() * 3;

  // 标记该轨道占用时长
  const estimatedPassTime = 2500;
  trackAvailable[track] = Date.now() + estimatedPassTime;

  const trackHeight = 100 / TRACK_COUNT;
  const topPercent = track * trackHeight + 1;

  const key = `d-${keyCounter++}`;
  const item: DanmakuItem = {
    key,
    name,
    text,
    avatar: p.avatar_url,
    initial: name.charAt(0).toUpperCase(),
    color: randomColor(p.id),
    style: {
      top: `${topPercent}%`,
      animationDuration: `${duration}s`,
    },
  };

  activeDanmakus.value.push(item);
  danmakuMeta.set(key, { createdAt: Date.now(), duration });

  danmakuIndex++;
  scheduleNext();
}

function scheduleNext() {
  const players = store.players;
  if (danmakuIndex >= players.length) {
    // 触发最后一次检查
    danmakuTimeout = setTimeout(spawnDanmaku, 100);
    return;
  }

  // 加速曲线：整体更快，555条约60秒内刷完
  const progress = danmakuIndex / players.length;
  let interval: number;
  if (progress > 0.85) interval = 40;
  else if (progress > 0.7) interval = 60;
  else if (progress > 0.5) interval = 80;
  else if (progress > 0.3) interval = 120;
  else if (progress > 0.1) interval = 180;
  else interval = 300;

  danmakuTimeout = setTimeout(spawnDanmaku, interval);
}

onMounted(() => {
  // 1秒后开始
  danmakuTimeout = setTimeout(spawnDanmaku, 1000);
});

onUnmounted(() => {
  clearTimeout(danmakuTimeout);
});
</script>

