<template>
  <div class="opening">
    <div class="text-container">
      <div v-for="(line, idx) in displayLines" :key="idx" class="line" :class="{ fading: line.fading }">
        {{ line.text }}
      </div>
      <span v-if="currentTyping" class="line typing">{{ currentTyping }}</span>
    </div>
  </div>
</template>

<script setup lang="ts">
import { useGameStore, GamePhase } from '../store';

const store = useGameStore();

interface DisplayLine {
  text: string;
  fading: boolean;
}

const displayLines = ref<DisplayLine[]>([]);
const currentTyping = ref('');

// 完整的情感蓄力序列
const sequence: { text: string; typeSpeed: number; holdTime: number; clear?: boolean }[] = [
  // 第一段：死亡回放
  { text: '8月31日。', typeSpeed: 200, holdTime: 2500 },
  { text: '呼吸的间隔越来越长。', typeSpeed: 120, holdTime: 2000 },
  { text: '长到你开始数。', typeSpeed: 150, holdTime: 1800 },
  { text: '长到你不敢数。', typeSpeed: 150, holdTime: 2500 },
  { text: '然后停了。', typeSpeed: 200, holdTime: 3500 },
  { text: '永远停在了十八岁。', typeSpeed: 150, holdTime: 4000, clear: true },

  // 第二段：第十条愿望
  { text: '……来世要娶我好不好。', typeSpeed: 180, holdTime: 3000 },
  { text: '她关掉了录音。', typeSpeed: 120, holdTime: 2000 },
  { text: '这个愿望在这一刻才真正被说出来。', typeSpeed: 100, holdTime: 1500 },
  { text: '但说的人已经不在了。', typeSpeed: 130, holdTime: 4000, clear: true },
];

function sleep(ms: number): Promise<void> {
  return new Promise(r => setTimeout(r, ms));
}

async function typeText(text: string, speed: number): Promise<void> {
  currentTyping.value = '';
  for (let i = 0; i < text.length; i++) {
    currentTyping.value += text[i];
    await sleep(speed);
  }
  // 打完后将当前行固化到 displayLines，清空 currentTyping
  displayLines.value.push({ text, fading: false });
  currentTyping.value = '';
}

async function clearScreen(): Promise<void> {
  for (const line of displayLines.value) {
    line.fading = true;
  }
  await sleep(1500);
  displayLines.value = [];
  await sleep(1000);
}

async function runSequence() {
  await sleep(2000); // 初始黑屏2秒

  for (const step of sequence) {
    await typeText(step.text, step.typeSpeed);
    await sleep(step.holdTime);

    if (step.clear) {
      await clearScreen();
    }
  }

  store.setPhase(GamePhase.TV_OFF);
}

onMounted(() => {
  runSequence();
});
</script>

