<template>
  <div class="shooter" ref="containerRef">
    <!-- HUD -->
    <div class="hud">
      <div class="lives">
        <template v-if="props.phase === 1">
          <span v-for="i in 3" :key="i" class="heart" :class="{ lost: i > store.lives }">♥</span>
        </template>
        <template v-else>
          <span class="life-count">♥ {{ store.lives }}</span>
          <div class="avatar-ring">
            <img
              v-for="p in visibleAvatars"
              :key="p.id"
              :src="p.avatar_url || ''"
              :alt="getDisplayName(p)"
              class="ring-avatar"
              @error="onAvatarError"
            />
          </div>
        </template>
      </div>
      <div class="wave-info" v-if="props.phase === 2">
        WAVE {{ currentWaveDisplay }} / 30
      </div>
    </div>

    <!-- Canvas游戏区域 -->
    <canvas ref="canvasRef" class="game-canvas"></canvas>
  </div>
</template>

<script setup lang="ts">
import { useGameStore, GamePhase } from '../store';
import { BOSS_PHASE1_TEXTS, BOSS_PHASE2_TEXTS, getDisplayName } from '../data';

const props = defineProps<{ phase: 1 | 2 }>();
const store = useGameStore();
const containerRef = ref<HTMLElement>();
const canvasRef = ref<HTMLCanvasElement>();
const currentWaveDisplay = ref(1);

// 第二阶段头像环
const visibleAvatars = computed(() => {
  if (props.phase !== 2) return [];
  const start = Math.max(0, store.totalPlayers - store.lives);
  return store.players.slice(start, start + 10);
});

function onAvatarError(e: Event) {
  (e.target as HTMLImageElement).style.display = 'none';
}

// ========== 游戏引擎 ==========

// BOSS类型
interface Boss {
  x: number;
  y: number;
  vx: number;
  vy: number;
  text: string;
  width: number;
  height: number;
  hp: number;
  maxHp: number;
  shootTimer: number;
  shootInterval: number;
}

// BOSS发射的弹幕（圆形散发）
interface EnemyBullet {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
}

// 玩家子弹
interface PlayerBullet {
  x: number;
  y: number;
  vy: number;
}

// 击碎粒子
interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  char: string;
}

let animId = 0;
let playerX = 0;
let playerY = 0;
const playerBullets: PlayerBullet[] = [];
const enemyBullets: EnemyBullet[] = [];
const bosses: Boss[] = [];
const particles: Particle[] = [];
let shootTimer = 0;
let currentWaveIndex = 0;
let invincibleTimer = 0;
let gameRunning = false;
let waveTransitioning = false;
let waveStarted = false; // BOSS是否已经生成过（防止生成前误触发波次切换）

const PLAYER_RADIUS = 3; // 玩家判定点很小（擦弹）
const PLAYER_VISUAL = props.phase === 1 ? 5 : 7;
const BULLET_SPEED = -10;
const SHOOT_INTERVAL = props.phase === 1 ? 6 : 3;

function getWaveTexts(): string[][] {
  return props.phase === 1 ? BOSS_PHASE1_TEXTS : BOSS_PHASE2_TEXTS;
}

function spawnBossesForWave(w: number, h: number) {
  const texts = getWaveTexts();
  const waveIdx = Math.min(currentWaveIndex, texts.length - 1);
  const waveTexts = texts[waveIdx];

  bosses.length = 0;
  enemyBullets.length = 0;
  waveTransitioning = false;
  waveStarted = true; // 标记BOSS已生成

  for (const text of waveTexts) {
    const charW = 16;
    const tw = text.length * charW + 24;
    const th = 36;

    // 第二阶段BOSS大幅增强
    const baseSpeed = props.phase === 1
      ? 1.0 + currentWaveIndex * 0.3
      : 2.0 + currentWaveIndex * 0.15 + Math.random() * 0.5;

    const angle = Math.random() * Math.PI * 2;
    const speed = baseSpeed + Math.random() * 0.5;

    // HP：第二阶段BOSS极为坚韧，最后一波几乎不可能打死
    const isLastWave = props.phase === 2 && currentWaveIndex >= 29;
    const hp = props.phase === 1
      ? 8 + currentWaveIndex * 3
      : isLastWave ? 9999 : 40 + currentWaveIndex * 8;

    // 弹幕发射间隔：第二阶段密集弹幕
    const shootInt = props.phase === 1
      ? Math.max(30, 80 - currentWaveIndex * 5)
      : Math.max(12, 35 - currentWaveIndex);

    bosses.push({
      x: 60 + Math.random() * (w - 120),
      y: 40 + Math.random() * (h * 0.35),
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      text,
      width: tw,
      height: th,
      hp,
      maxHp: hp,
      shootTimer: Math.floor(Math.random() * shootInt),
      shootInterval: shootInt,
    });
  }
}

function bossShoot(boss: Boss) {
  // 第二阶段：更密集的弹幕模式
  const bulletCount = props.phase === 1
    ? 6 + Math.min(currentWaveIndex, 6) * 2
    : 12 + Math.min(currentWaveIndex, 15) * 2;

  const bulletSpeed = props.phase === 1
    ? 1.5 + currentWaveIndex * 0.1
    : 2.2 + currentWaveIndex * 0.08;

  const angleOffset = Math.random() * Math.PI * 2;

  for (let i = 0; i < bulletCount; i++) {
    const angle = angleOffset + (i / bulletCount) * Math.PI * 2;
    enemyBullets.push({
      x: boss.x,
      y: boss.y,
      vx: Math.cos(angle) * bulletSpeed,
      vy: Math.sin(angle) * bulletSpeed,
      radius: props.phase === 1 ? 4 : 3.5,
    });
  }

  // 第二阶段额外散射：每隔几波增加一种弹幕模式
  if (props.phase === 2 && currentWaveIndex >= 5) {
    // 追加一圈慢速大弹
    const slowCount = 6;
    const slowSpeed = 1.0;
    for (let i = 0; i < slowCount; i++) {
      const angle = angleOffset + Math.PI / bulletCount + (i / slowCount) * Math.PI * 2;
      enemyBullets.push({
        x: boss.x,
        y: boss.y,
        vx: Math.cos(angle) * slowSpeed,
        vy: Math.sin(angle) * slowSpeed,
        radius: 6,
      });
    }
  }

  if (props.phase === 2 && currentWaveIndex >= 15) {
    // 追加瞄准弹（朝向玩家）
    const dx = playerX - boss.x;
    const dy = playerY - boss.y;
    const dist = Math.sqrt(dx * dx + dy * dy) || 1;
    const aimSpeed = 3.0;
    for (let s = -1; s <= 1; s++) {
      const spreadAngle = s * 0.15;
      const ax = dx / dist;
      const ay = dy / dist;
      const rx = ax * Math.cos(spreadAngle) - ay * Math.sin(spreadAngle);
      const ry = ax * Math.sin(spreadAngle) + ay * Math.cos(spreadAngle);
      enemyBullets.push({
        x: boss.x,
        y: boss.y,
        vx: rx * aimSpeed,
        vy: ry * aimSpeed,
        radius: 4,
      });
    }
  }
}

function createBossDeathParticles(boss: Boss) {
  for (const char of boss.text) {
    for (let j = 0; j < 2; j++) {
      particles.push({
        x: boss.x + (Math.random() - 0.5) * boss.width,
        y: boss.y + (Math.random() - 0.5) * boss.height,
        vx: (Math.random() - 0.5) * 6,
        vy: (Math.random() - 0.5) * 6 - 2,
        life: 50 + Math.random() * 30,
        maxLife: 80,
        char,
      });
    }
  }
}

function gameLoop(ctx: CanvasRenderingContext2D, w: number, h: number) {
  if (!gameRunning) return;

  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, w, h);

  // === 玩家自动发射子弹 ===
  shootTimer++;
  if (shootTimer >= SHOOT_INTERVAL) {
    shootTimer = 0;
    if (props.phase === 1) {
      playerBullets.push({ x: playerX, y: playerY - 10, vy: BULLET_SPEED });
    } else {
      // 三路散射
      playerBullets.push({ x: playerX, y: playerY - 10, vy: BULLET_SPEED });
      playerBullets.push({ x: playerX - 8, y: playerY - 8, vy: BULLET_SPEED });
      playerBullets.push({ x: playerX + 8, y: playerY - 8, vy: BULLET_SPEED });
    }
  }

  // === 更新玩家子弹 ===
  for (let i = playerBullets.length - 1; i >= 0; i--) {
    const b = playerBullets[i];
    b.y += b.vy;
    if (b.y < -10) {
      playerBullets.splice(i, 1);
      continue;
    }
    ctx.fillStyle = props.phase === 1 ? '#fff' : '#7dd3fc';
    ctx.fillRect(b.x - 1.5, b.y, 3, 10);
  }

  // === 更新BOSS ===
  for (let i = bosses.length - 1; i >= 0; i--) {
    const boss = bosses[i];

    // 移动（弹球式反弹）
    boss.x += boss.vx;
    boss.y += boss.vy;

    // 边界反弹
    if (boss.x - boss.width / 2 < 0) {
      boss.x = boss.width / 2;
      boss.vx = Math.abs(boss.vx);
    }
    if (boss.x + boss.width / 2 > w) {
      boss.x = w - boss.width / 2;
      boss.vx = -Math.abs(boss.vx);
    }
    if (boss.y - boss.height / 2 < 0) {
      boss.y = boss.height / 2;
      boss.vy = Math.abs(boss.vy);
    }
    if (boss.y + boss.height / 2 > h * 0.65) {
      boss.y = h * 0.65 - boss.height / 2;
      boss.vy = -Math.abs(boss.vy);
    }

    // BOSS发射弹幕
    boss.shootTimer++;
    if (boss.shootTimer >= boss.shootInterval) {
      boss.shootTimer = 0;
      bossShoot(boss);
    }

    // 玩家子弹 vs BOSS碰撞
    for (let j = playerBullets.length - 1; j >= 0; j--) {
      const b = playerBullets[j];
      if (
        b.x > boss.x - boss.width / 2 &&
        b.x < boss.x + boss.width / 2 &&
        b.y > boss.y - boss.height / 2 &&
        b.y < boss.y + boss.height / 2
      ) {
        playerBullets.splice(j, 1);
        boss.hp--;
        // 被击中闪白
        if (boss.hp <= 0) {
          createBossDeathParticles(boss);
          bosses.splice(i, 1);
          break;
        }
      }
    }

    // 绘制BOSS（仍在列表中）
    if (bosses[i]) {
      const b = bosses[i];
      // 背景框
      const hpRatio = b.hp / b.maxHp;
      const frameColor = props.phase === 1
        ? `rgba(255, 255, 255, ${0.15 + (1 - hpRatio) * 0.2})`
        : `rgba(200, 60, 60, ${0.2 + (1 - hpRatio) * 0.3})`;

      ctx.strokeStyle = frameColor;
      ctx.lineWidth = 1;
      ctx.strokeRect(b.x - b.width / 2, b.y - b.height / 2, b.width, b.height);

      // HP条
      ctx.fillStyle = 'rgba(255, 255, 255, 0.15)';
      ctx.fillRect(b.x - b.width / 2, b.y + b.height / 2 + 2, b.width, 3);
      ctx.fillStyle = props.phase === 1 ? '#888' : '#e55';
      ctx.fillRect(b.x - b.width / 2, b.y + b.height / 2 + 2, b.width * hpRatio, 3);

      // 文字
      ctx.fillStyle = props.phase === 1 ? '#ddd' : '#faa';
      ctx.font = '15px "Noto Serif SC", "SimSun", serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(b.text, b.x, b.y);
    }
  }

  // === 更新敌方弹幕 ===
  for (let i = enemyBullets.length - 1; i >= 0; i--) {
    const eb = enemyBullets[i];
    eb.x += eb.vx;
    eb.y += eb.vy;

    // 超出边界删除
    if (eb.x < -20 || eb.x > w + 20 || eb.y < -20 || eb.y > h + 20) {
      enemyBullets.splice(i, 1);
      continue;
    }

    // 绘制弹幕（圆形）
    ctx.beginPath();
    ctx.arc(eb.x, eb.y, eb.radius, 0, Math.PI * 2);
    ctx.fillStyle = props.phase === 1
      ? 'rgba(255, 120, 120, 0.8)'
      : 'rgba(255, 80, 80, 0.9)';
    ctx.fill();
    ctx.beginPath();
    ctx.arc(eb.x, eb.y, eb.radius * 0.5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.6)';
    ctx.fill();

    // 碰撞检测：弹幕 vs 玩家
    // 最后一波（第30波）去掉无敌时间，碰到就掉命，快速清零
    const isLastWaveNow = props.phase === 2 && currentWaveIndex >= 29;
    const canBeHit = isLastWaveNow || invincibleTimer <= 0;

    if (canBeHit) {
      const dx = playerX - eb.x;
      const dy = playerY - eb.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < eb.radius + PLAYER_RADIUS) {
        store.loseLife();

        if (isLastWaveNow) {
          // 最后一波：不给无敌时间，但每帧只掉一次命（避免瞬间清零）
          invincibleTimer = 3; // 极短无敌（约0.05秒），让弹幕有时间移过判定点
        } else {
          invincibleTimer = 120; // 正常2秒无敌
        }

        // 闪红（最后一波轻微闪红）
        ctx.fillStyle = isLastWaveNow
          ? 'rgba(255, 0, 0, 0.1)'
          : 'rgba(255, 0, 0, 0.25)';
        ctx.fillRect(0, 0, w, h);

        // 被击中时清除附近弹幕（正常波次给喘息，最后一波不清除）
        if (!isLastWaveNow) {
          for (let k = enemyBullets.length - 1; k >= 0; k--) {
            const ek = enemyBullets[k];
            const dd = Math.sqrt((playerX - ek.x) ** 2 + (playerY - ek.y) ** 2);
            if (dd < 80) enemyBullets.splice(k, 1);
          }
        }

        if (store.lives <= 0) {
          gameRunning = false;
          cancelAnimationFrame(animId);
          if (props.phase === 1) {
            store.setPhase(GamePhase.DEATH);
          } else {
            store.setPhase(GamePhase.FINALE);
          }
          return;
        }
        break;
      }
    }
  }

  // === 更新粒子 ===
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.05; // 重力
    p.life--;
    if (p.life <= 0) {
      particles.splice(i, 1);
      continue;
    }
    const alpha = p.life / p.maxLife;
    ctx.globalAlpha = alpha;
    ctx.fillStyle = props.phase === 1 ? '#999' : '#fcc';
    ctx.font = '13px "Noto Serif SC", serif';
    ctx.textAlign = 'center';
    ctx.fillText(p.char, p.x, p.y);
    ctx.globalAlpha = 1;
  }

  // === 绘制玩家 ===
  if (invincibleTimer > 0) {
    invincibleTimer--;
    // 无敌闪烁
    if (Math.floor(invincibleTimer / 4) % 2 === 0) {
      drawPlayer(ctx);
    }
    // 绘制判定点（无敌时也显示）
    ctx.beginPath();
    ctx.arc(playerX, playerY, PLAYER_RADIUS, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
    ctx.fill();
  } else {
    drawPlayer(ctx);
  }

  // === 波次管理（只在BOSS已生成过且全部击杀后触发） ===
  if (waveStarted && bosses.length === 0 && !waveTransitioning) {
    waveTransitioning = true;

    // 清除残留弹幕
    setTimeout(() => {
      enemyBullets.length = 0;
    }, 500);

    setTimeout(() => {
      if (!gameRunning) return;
      currentWaveIndex++;
      currentWaveDisplay.value = currentWaveIndex + 1;

      const maxWaves = props.phase === 1 ? BOSS_PHASE1_TEXTS.length : 30;

      if (props.phase === 2 && currentWaveIndex >= maxWaves) {
        gameRunning = false;
        cancelAnimationFrame(animId);
        store.setPhase(GamePhase.FINALE);
        return;
      }

      if (props.phase === 2) {
        // 每波结束展示IF线图片
        gameRunning = false;
        cancelAnimationFrame(animId);
        store.showIfImage(currentWaveIndex - 1);
        store.setPhase(GamePhase.IF_IMAGE);
        return;
      }

      // 第一阶段：无限循环到死
      enemyBullets.length = 0;
      spawnBossesForWave(w, h);
    }, 1500);
  }

  animId = requestAnimationFrame(() => gameLoop(ctx, w, h));
}

function drawPlayer(ctx: CanvasRenderingContext2D) {
  if (props.phase === 1) {
    // 白色光点
    ctx.beginPath();
    ctx.arc(playerX, playerY, PLAYER_VISUAL, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.3)';
    ctx.fill();
    ctx.beginPath();
    ctx.arc(playerX, playerY, PLAYER_RADIUS + 1, 0, Math.PI * 2);
    ctx.fillStyle = '#fff';
    ctx.fill();
  } else {
    // 彩色光点
    const gradient = ctx.createRadialGradient(playerX, playerY, 0, playerX, playerY, PLAYER_VISUAL * 2);
    gradient.addColorStop(0, 'rgba(125, 211, 252, 0.8)');
    gradient.addColorStop(0.5, 'rgba(56, 189, 248, 0.3)');
    gradient.addColorStop(1, 'transparent');
    ctx.beginPath();
    ctx.arc(playerX, playerY, PLAYER_VISUAL * 2, 0, Math.PI * 2);
    ctx.fillStyle = gradient;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(playerX, playerY, PLAYER_RADIUS + 1, 0, Math.PI * 2);
    ctx.fillStyle = '#fff';
    ctx.fill();
  }
}

function onMouseMove(e: MouseEvent) {
  if (!canvasRef.value) return;
  const rect = canvasRef.value.getBoundingClientRect();
  playerX = (e.clientX - rect.left) * (canvasRef.value.width / rect.width);
  playerY = (e.clientY - rect.top) * (canvasRef.value.height / rect.height);
}

function onTouchMove(e: TouchEvent) {
  e.preventDefault();
  if (!canvasRef.value || !e.touches[0]) return;
  const rect = canvasRef.value.getBoundingClientRect();
  playerX = (e.touches[0].clientX - rect.left) * (canvasRef.value.width / rect.width);
  playerY = (e.touches[0].clientY - rect.top) * (canvasRef.value.height / rect.height);
}

onMounted(() => {
  const canvas = canvasRef.value!;
  const container = containerRef.value!;
  const w = container.clientWidth;
  const h = container.clientHeight;

  // 高DPI适配
  const dpr = window.devicePixelRatio || 1;
  canvas.width = w * dpr;
  canvas.height = h * dpr;
  canvas.style.width = w + 'px';
  canvas.style.height = h + 'px';
  const ctx = canvas.getContext('2d')!;
  ctx.scale(dpr, dpr);

  // 实际逻辑用CSS尺寸
  const logicW = w;
  const logicH = h;

  playerX = logicW / 2;
  playerY = logicH - 80;

  // 重置游戏状态
  playerBullets.length = 0;
  enemyBullets.length = 0;
  bosses.length = 0;
  particles.length = 0;
  shootTimer = 0;
  currentWaveIndex = store.currentWave;
  currentWaveDisplay.value = currentWaveIndex + 1;
  invincibleTimer = 0;
  waveTransitioning = false;
  waveStarted = false; // 重置：等待BOSS生成后才允许波次切换
  gameRunning = true;

  // 第二阶段：只在第一次进入时设置555条命，后续从IF图片返回时保持当前命数
  if (props.phase === 2 && store.lives <= 3) {
    store.setLives(store.totalPlayers);
  }

  // 第二阶段从IF返回时立即出BOSS（不延迟），首次进入延迟1.5秒
  const isReturningFromIF = props.phase === 2 && store.currentWave > 0;
  const spawnDelay = isReturningFromIF ? 300 : 1500;

  setTimeout(() => {
    if (gameRunning) {
      spawnBossesForWave(logicW, logicH);
    }
  }, spawnDelay);

  gameLoop(ctx, logicW, logicH);

  canvas.addEventListener('mousemove', onMouseMove);
  canvas.addEventListener('touchmove', onTouchMove, { passive: false });
});

onUnmounted(() => {
  gameRunning = false;
  cancelAnimationFrame(animId);
  canvasRef.value?.removeEventListener('mousemove', onMouseMove);
  canvasRef.value?.removeEventListener('touchmove', onTouchMove);
});
</script>

<style scoped>
