<template>
  <div class="death" ref="containerRef">
    <div class="frozen-screen" :class="{ grayscale: isGray }">
      <div class="static-text" v-if="showGameOver">GAME OVER</div>
    </div>
    <div class="shatter-overlay" v-if="showShatter">
      <div
        v-for="i in 20"
        :key="i"
        class="shard"
        :style="shardStyle(i)"
      ></div>
    </div>
    <div class="black-overlay" :class="{ active: fadeToBlack }">
      <!-- 死亡后的情感过渡文字 -->
      <div class="death-text" v-if="showDeathText">
        <div
          v-for="(line, idx) in deathLines"
          :key="idx"
          class="death-line"
          :class="{ visible: line.visible, fading: line.fading }"
        >
          {{ line.text }}
        </div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { useGameStore, GamePhase } from '../store';

const store = useGameStore();
const containerRef = ref<HTMLElement>();
const isGray = ref(false);
const showGameOver = ref(true);
const showShatter = ref(false);
const fadeToBlack = ref(false);
const showDeathText = ref(false);

interface DeathLine {
  text: string;
  visible: boolean;
  fading: boolean;
}

const deathLines = ref<DeathLine[]>([
  { text: '对面那扇门不会再响了。', visible: false, fading: false },
]);

function shardStyle(i: number) {
  const angle = (i / 20) * 360;
  const tx = Math.cos((angle * Math.PI) / 180) * (100 + Math.random() * 200);
  const ty = Math.sin((angle * Math.PI) / 180) * (100 + Math.random() * 200);
  return {
    '--tx': `${tx}px`,
    '--ty': `${ty}px`,
    '--rot': `${Math.random() * 360}deg`,
    '--delay': `${Math.random() * 0.3}s`,
    left: `${30 + Math.random() * 40}%`,
    top: `${30 + Math.random() * 40}%`,
    width: `${20 + Math.random() * 60}px`,
    height: `${20 + Math.random() * 40}px`,
  };
}

onMounted(() => {
  // 1. 瞬间变黑白
  isGray.value = true;

  // 2. 停顿2秒
  setTimeout(() => {
    // 3. 碎裂效果
    showShatter.value = true;

    setTimeout(() => {
      // 4. 渐变为纯黑屏
      fadeToBlack.value = true;
      showGameOver.value = false;

      // 5. 黑屏后显示过渡文字
      setTimeout(() => {
        showDeathText.value = true;

        // 逐行显示
        setTimeout(() => {
          deathLines.value[0].visible = true;
        }, 1000);

        // 停留后淡出
        setTimeout(() => {
          deathLines.value[0].fading = true;
        }, 5000);

        // 进入玩家弹幕
        setTimeout(() => {
          store.setPhase(GamePhase.PLAYER_DANMAKU);
        }, 7000);
      }, 1500);
    }, 1500);
  }, 2000);
});
</script>

<style scoped>
.death {
  width: 100%;
  height: 100%;
  position: relative;
  background: #000;
  overflow: hidden;
}

.frozen-screen {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: filter 0.1s;
}

.frozen-screen.grayscale {
  filter: grayscale(1);
}

.static-text {
  color: rgba(255, 255, 255, 0.3);
  font-size: 24px;
  letter-spacing: 8px;
}

.shatter-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
}

.shard {
  position: absolute;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.2);
  animation: shatter 1.2s var(--delay, 0s) ease-out forwards;
}

@keyframes shatter {
  0% {
    transform: translate(0, 0) rotate(0deg);
    opacity: 1;
  }
  100% {
    transform: translate(var(--tx), var(--ty)) rotate(var(--rot));
    opacity: 0;
  }
}

.black-overlay {
  position: absolute;
  inset: 0;
  background: #000;
  opacity: 0;
  transition: opacity 1s ease;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
}

.black-overlay.active {
  opacity: 1;
}

.death-text {
  text-align: center;
  padding: 0 20px;
}

.death-line {
  color: #fff;
  font-size: 20px;
  letter-spacing: 4px;
  font-weight: 300;
  font-family: 'Noto Serif SC', 'SimSun', serif;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 2s ease, transform 2s ease;
}

.death-line.visible {
  opacity: 0.7;
  transform: translateY(0);
}

.death-line.fading {
  opacity: 0;
  transform: translateY(-5px);
}
</style>
