<template>
  <div class="tv-off" ref="containerRef">
    <!-- CRT扫描线效果 -->
    <div class="scanlines" :class="{ active: showScanlines }"></div>
    <!-- 内容区域（会被压缩）——空白，只做视觉过渡 -->
    <div class="content" ref="contentRef">
      <span class="text"></span>
    </div>
    <!-- 压缩成的白线 -->
    <div class="white-line" ref="lineRef" v-show="showLine"></div>
    <!-- 亮点 -->
    <div class="bright-dot" ref="dotRef" v-show="showDot"></div>
  </div>
</template>

<script setup lang="ts">
import { useGameStore, GamePhase } from '../store';
import gsap from 'gsap';

const store = useGameStore();
const containerRef = ref<HTMLElement>();
const contentRef = ref<HTMLElement>();
const lineRef = ref<HTMLElement>();
const dotRef = ref<HTMLElement>();

const showScanlines = ref(true);
const showLine = ref(false);
const showDot = ref(false);

onMounted(() => {
  const tl = gsap.timeline();

  // 1. 画面闪烁 + 噪点
  tl.to(containerRef.value!, {
    duration: 0.1,
    opacity: 0.7,
    repeat: 3,
    yoyo: true,
  });

  // 2. 画面压缩成白线
  tl.to(contentRef.value!, {
    duration: 0.5,
    scaleY: 0.005,
    ease: 'power2.in',
    onComplete: () => {
      showLine.value = true;
    },
  });

  // 3. 隐藏内容，显示白线
  tl.set(contentRef.value!, { display: 'none' });

  // 4. 白线持续0.3秒
  tl.to(lineRef.value!, {
    duration: 0.3,
    opacity: 1,
  });

  // 5. 白线缩成亮点
  tl.to(lineRef.value!, {
    duration: 0.3,
    scaleX: 0,
    ease: 'power2.in',
    onComplete: () => {
      showLine.value = false;
      showDot.value = true;
    },
  });

  // 6. 亮点消失
  tl.to(dotRef.value!, {
    duration: 0.5,
    scale: 0,
    opacity: 0,
    ease: 'power2.out',
    onComplete: () => {
      showDot.value = false;
      showScanlines.value = false;
    },
  });

  // 7. 完全黑屏后进入灵魂之问
  tl.to({}, {
    duration: 1.5,
    onComplete: () => {
      store.setPhase(GamePhase.QUESTION);
    },
  });
});
</script>

