<template>
  <div class="if-image">
    <div class="white-flash" :class="{ active: showFlash }"></div>
    <div class="image-container" :class="{ show: showImage }">
      <img
        :src="currentImageSrc"
        class="if-photo"
        @error="onImageError"
      />
      <div v-if="imageError" class="placeholder">
        <div class="placeholder-text">IF #{{ store.currentIfImage + 1 }}</div>
        <div class="placeholder-hint">images/if_{{ String(store.currentIfImage + 1).padStart(2, '0') }}.png</div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { useGameStore, GamePhase } from '../store';
import { IF_IMAGES } from '../data';

const store = useGameStore();
const showFlash = ref(true);
const showImage = ref(false);
const imageError = ref(false);

const currentImageSrc = computed(() => IF_IMAGES[store.currentIfImage] || '');

function onImageError() {
  imageError.value = true;
}

onMounted(() => {
  // 白闪效果
  setTimeout(() => {
    showFlash.value = false;
    showImage.value = true;

    // 图片展示15秒后返回射击
    setTimeout(() => {
      showImage.value = false;
      imageError.value = false;

      setTimeout(() => {
        store.nextWave();
        store.setPhase(GamePhase.SHOOTER_PHASE2);
      }, 500);
    }, 15000);
  }, 300);
});
</script>

